CREATE OR REPLACE FUNCTION public.admin_track_document_file_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  submission_row public.document_submissions%ROWTYPE;
  submission_id uuid;
  resource_key text;
BEGIN
  submission_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.submission_id ELSE NEW.submission_id END;
  SELECT * INTO submission_row FROM public.document_submissions WHERE id = submission_id;
  IF FOUND THEN
    resource_key := CASE WHEN submission_row.submission_scope::text = 'renewal' OR submission_row.renewal_id IS NOT NULL THEN 'renewals' ELSE 'registration' END;
    PERFORM public.admin_bump_portal_change_version(resource_key);
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.submission_id IS DISTINCT FROM NEW.submission_id THEN
    SELECT * INTO submission_row FROM public.document_submissions WHERE id = OLD.submission_id;
    IF FOUND THEN
      resource_key := CASE WHEN submission_row.submission_scope::text = 'renewal' OR submission_row.renewal_id IS NOT NULL THEN 'renewals' ELSE 'registration' END;
      PERFORM public.admin_bump_portal_change_version(resource_key);
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_track_document_submission_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  old_resource text;
  new_resource text;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    old_resource := CASE WHEN OLD.submission_scope::text = 'renewal' OR OLD.renewal_id IS NOT NULL THEN 'renewals' ELSE 'registration' END;
    PERFORM public.admin_bump_portal_change_version(old_resource);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    new_resource := CASE WHEN NEW.submission_scope::text = 'renewal' OR NEW.renewal_id IS NOT NULL THEN 'renewals' ELSE 'registration' END;
    IF new_resource IS DISTINCT FROM old_resource THEN
      PERFORM public.admin_bump_portal_change_version(new_resource);
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_renewal_terminal_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF old.status IN ('approved', 'rejected') THEN
      IF current_setting('app.allow_test_scenario_prep', true) = 'true' THEN
        IF EXISTS (
          SELECT 1 FROM public.organization_profiles op
          WHERE op.id = old.organization_id
            AND (op.is_renewal_test_account = true)
        ) THEN
          RETURN new;
        END IF;
      END IF;
      RAISE EXCEPTION 'Terminal renewal records cannot be modified.';
    END IF;
    RETURN new;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF current_setting('app.allow_org_deletion', true) = 'true' THEN
      RETURN old;
    END IF;
    IF current_setting('app.allow_test_scenario_prep', true) = 'true' THEN
      IF EXISTS (
        SELECT 1 FROM public.organization_profiles op
        WHERE op.id = old.organization_id
          AND (op.is_renewal_test_account = true)
      ) THEN
        RETURN old;
      END IF;
    END IF;
    IF old.status IN ('approved', 'rejected') THEN
      RAISE EXCEPTION 'Terminal renewal records cannot be deleted.';
    END IF;
    RETURN old;
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.evaluate_and_apply_automatic_registration_verification(_organization_id uuid, _admin_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(verified boolean, urn text, already_verified boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _target_org public.organization_profiles%rowtype;
  _reg_submission_id uuid;
  _required_type_ids uuid[];
  _required_count int;
  _approved_count int;
  _official_urn text;
  _effective_verified_at timestamptz := clock_timestamp();
  _start_date date;
  _end_date date;
  _notify_approved boolean;
begin
  -- 1. Fetch target organization profile
  select *
  into _target_org
  from public.organization_profiles
  where id = _organization_id;

  if _target_org.id is null then
    return query select false, null::text, false, 'Organization profile not found.';
    return;
  end if;

  -- 2. If already verified or suspended, do not re-verify
  if _target_org.profile_status = 'verified' then
    return query select true, _target_org.urn, true, 'Organization is already verified.';
    return;
  end if;

  if _target_org.profile_status = 'suspended_inactive' then
    return query select false, null::text, false, 'Organization is suspended and cannot be verified.';
    return;
  end if;

  -- 3. Resolve parent initial registration document submission (renewal_id is null)
  select id
  into _reg_submission_id
  from public.document_submissions
  where organization_id = _organization_id
    and renewal_id is null
  order by created_at desc
  limit 1;

  if _reg_submission_id is null then
    return query select false, null::text, false, 'No initial registration document submission found.';
    return;
  end if;

  -- 4. Dynamic required document types
  select coalesce(array_agg(rdt.id), '{}'::uuid[])
  into _required_type_ids
  from public.required_document_types rdt
  where rdt.is_active = true
    and coalesce(rdt.is_required, true) = true
    and coalesce(rdt.template_scope, 'document_submission') = 'document_submission'
    and (rdt.scope is null or rdt.scope in ('registration', 'both'))
    and (
      rdt.template_category is null
      or rdt.template_category = '{}'
      or 'yorp' = any(rdt.template_category)
    );

  -- Fallback if no specific registration tags are set
  if array_length(_required_type_ids, 1) is null or array_length(_required_type_ids, 1) = 0 then
    select coalesce(array_agg(rdt.id), '{}'::uuid[])
    into _required_type_ids
    from public.required_document_types rdt
    where rdt.is_active = true;
  end if;

  _required_count := coalesce(array_length(_required_type_ids, 1), 0);

  if _required_count = 0 then
    return query select false, null::text, false, 'No active required document types configured in system.';
    return;
  end if;

  -- 5. Count approved files for required document types
  select count(distinct dsf.document_type_id)
  into _approved_count
  from public.document_submission_files dsf
  where dsf.submission_id = _reg_submission_id
    and dsf.document_type_id = any(_required_type_ids)
    and dsf.admin_status = 'approved_green';

  -- If any required document type is not approved, block verification
  if _approved_count < _required_count then
    return query select false, null::text, false,
      format('Incomplete: %s of %s required registration documents approved.', _approved_count, _required_count);
    return;
  end if;

  -- 6. ALL REQUIRED REGISTRATION DOCUMENTS ARE APPROVED -> PROCEED WITH AUTOMATIC VERIFICATION
  _start_date := date(_effective_verified_at);
  _end_date := (_start_date + interval '3 years')::date;

  -- Preserve existing URN if already present, otherwise generate deterministic official URN (BB-YY-NNN)
  if _target_org.urn is not null and trim(_target_org.urn) <> '' then
    _official_urn := trim(_target_org.urn);
  elsif _target_org.is_existing_organization and _target_org.organization_identifier_number is not null and trim(_target_org.organization_identifier_number) <> '' then
    _official_urn := trim(_target_org.organization_identifier_number);
  else
    _official_urn := public.generate_unique_urn(_target_org.barangay, _effective_verified_at);
  end if;

  -- 7. Update organization profile with official verified status and assigned URN (using actual schema)
  update public.organization_profiles
  set
    profile_status = 'verified'::public.profile_status,
    verified_at = _effective_verified_at,
    urn = _official_urn,
    urn_normalized = public.normalize_urn(_official_urn),
    organization_identifier_number = _official_urn,
    urn_review_status = 'verified'::public.urn_review_status,
    verification_method = coalesce(_target_org.verification_method, 'documents'::public.verification_method),
    updated_at = _effective_verified_at
  where id = _organization_id;

  -- 8. Create Term 1 accreditation record if not already present
  if not exists (
    select 1 from public.organization_accreditations
    where organization_id = _organization_id and term_number = 1
  ) then
    insert into public.organization_accreditations (
      organization_id,
      term_number,
      start_date,
      end_date,
      certificate_urn,
      status,
      is_legacy_inferred,
      approved_by,
      approved_at,
      created_at
    ) values (
      _organization_id,
      1,
      _start_date,
      _end_date,
      _official_urn,
      'active',
      false,
      _admin_id,
      _effective_verified_at,
      _effective_verified_at
    );
  end if;

  -- 9. Canonical Activity Log
  insert into public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description,
    created_at
  ) values (
    _admin_id,
    _organization_id,
    'Verified organization registration',
    'organization_profile',
    _organization_id,
    format('Organization registration verified automatically upon approval of all required documents. Assigned URN: %s (Valid until %s).', _official_urn, _end_date),
    _effective_verified_at
  );

  -- 10. Gated In-App Notification based on workflow.notify_org_on_approved
  _notify_approved := public.get_system_setting_bool('workflow.notify_org_on_approved', true);
  if _target_org.user_id is not null and _notify_approved then
    insert into public.notifications (
      user_id,
      organization_id,
      title,
      message,
      type,
      related_type,
      related_id,
      created_at
    ) values (
      _target_org.user_id,
      _organization_id,
      'Registration Approved & Verified',
      format('Congratulations! Your organization registration has been approved and verified. Your official URN is %s.', _official_urn),
      'completed',
      'organization_profile',
      _organization_id,
      _effective_verified_at
    );
  end if;

  return query select true, _official_urn, false, 'Registration successfully verified.';
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_renewal_test_registration_packet_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _submission_id uuid;
  _is_seeded_registration boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'document_submission_files'
     AND TG_OP = 'INSERT'
     AND current_setting('app.seed_renewal_test_registration_documents', true) = 'true' THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'document_submissions' THEN
    _submission_id := OLD.id;
    _is_seeded_registration :=
      OLD.is_seeded_sample_data IS TRUE
      AND OLD.seed_batch = 'RENEWAL-TEST-REGISTRATION'
      AND OLD.submission_scope = 'registration'
      AND OLD.renewal_id IS NULL;
  ELSE
    IF TG_OP = 'INSERT' THEN
      _submission_id := NEW.submission_id;
    ELSE
      _submission_id := OLD.submission_id;
    END IF;
    SELECT EXISTS (
      SELECT 1
      FROM public.document_submissions submission
      WHERE (submission.id = _submission_id
         OR (TG_OP = 'UPDATE' AND submission.id = NEW.submission_id))
        AND submission.is_seeded_sample_data IS TRUE
        AND submission.seed_batch = 'RENEWAL-TEST-REGISTRATION'
        AND submission.submission_scope = 'registration'
        AND submission.renewal_id IS NULL
    ) INTO _is_seeded_registration;
  END IF;

  IF _is_seeded_registration THEN
    RAISE EXCEPTION 'The Renewal Test Organization registration packet is an immutable Cycle 1 record.';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_submitted_registration_document_edits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  _submission_status text;
  _registration_submission boolean;
begin
  -- Admin and correction RPCs run with their validated definer privileges.
  if current_user not in ('authenticated', 'anon')
     or public.current_user_is_admin() then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  select ds.status,
         ds.submission_scope = 'registration' and ds.renewal_id is null
    into _submission_status, _registration_submission
  from public.document_submissions ds
  where ds.id = old.submission_id
  for update;

  if old.admin_status is distinct from 'draft'
     or _submission_status is null
     or not (
       _submission_status in ('draft', 'needs_revision')
       or (
         _registration_submission is true
         and _submission_status in ('under_admin_review', 'submitted', 'ready_for_review')
       )
     ) then
    raise exception 'Submitted documents are locked. Only draft documents can be edited or removed; requested revisions must use the replacement flow.';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_submission_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  org_user_id uuid;
  notif_type public.notification_type;
  notif_title text;
  notif_message text;
begin
  select op.user_id into org_user_id
  from public.organization_profiles op
  where op.id = new.organization_id;

  if org_user_id is null then
    return new;
  end if;

  if new.status = 'needs_revision' then
    notif_type := 'document_revision';
    notif_title := 'Document revision requested';
    notif_message := 'Your document submission has been marked needs revision.';
  elsif new.status = 'approved_green' then
    notif_type := 'document_green';
    notif_title := 'Document submission approved';
    notif_message := 'Your document submission has been marked approved.';
  elsif new.status = 'rejected_red' then
    notif_type := 'document_red';
    notif_title := 'Document submission rejected';
    notif_message := 'Your document submission has been marked rejected.';
  else
    return new;
  end if;

  insert into public.notifications (user_id, organization_id, title, message, type, related_type, related_id)
  values (org_user_id, new.organization_id, notif_title, notif_message, notif_type, 'document_submission', new.id);

  insert into public.activity_logs (actor_user_id, organization_id, action, related_type, related_id, description)
  values (coalesce(new.reviewed_by, auth.uid()), new.organization_id, 'reviewed_documents', 'document_submission', new.id, notif_message);

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.user_replace_document_submission_file(_file_id uuid, _new_file_url text, _new_file_name text, _new_file_type text, _new_file_size numeric DEFAULT NULL::numeric, _submit_for_review boolean DEFAULT true)
 RETURNS document_submission_files
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _old_file record;
  _submission record;
  _owner_id uuid;
  _history jsonb;
  _history_entry jsonb;
  _updated_row public.document_submission_files;
BEGIN
  SELECT * INTO _old_file
  FROM public.document_submission_files
  WHERE id = _file_id;

  IF _old_file.id IS NULL THEN
    RAISE EXCEPTION 'Document file not found.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE id = _old_file.submission_id;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'Parent document submission not found.';
  END IF;

  SELECT user_id INTO _owner_id
  FROM public.organization_profiles
  WHERE id = _submission.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this submission.';
  END IF;

  _history_entry := jsonb_build_object(
    'action', 'replaced',
    'previousFileName', _old_file.file_name,
    'previousFileUrl', _old_file.file_url,
    'previousFileType', _old_file.file_type,
    'previousFileSize', _old_file.file_size,
    'previousStatus', _old_file.admin_status,
    'adminRemarks', _old_file.admin_remarks,
    'reviewedAt', _old_file.reviewed_at,
    'replacedAt', clock_timestamp()
  );

  _history := coalesce(_old_file.revision_history, '[]'::jsonb) || jsonb_build_array(_history_entry);

  UPDATE public.document_submission_files
  SET
    file_url = _new_file_url,
    file_name = _new_file_name,
    file_type = _new_file_type,
    file_size = coalesce(_new_file_size, _old_file.file_size),
    admin_status = CASE
      WHEN _submit_for_review THEN 'submitted'::public.document_submission_status
      ELSE 'draft'::public.document_submission_status
    END,
    admin_remarks = NULL,
    reviewed_at = NULL,
    uploaded_at = clock_timestamp(),
    updated_at = clock_timestamp(),
    revision_history = _history
  WHERE id = _file_id
  RETURNING * INTO _updated_row;

  RETURN _updated_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_resubmit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'needs_revision' THEN
    RAISE EXCEPTION 'Renewal cannot be resubmitted from status "%". Expected "needs_revision".', _renewal.status;
  END IF;

  -- Verify within 180-day window
  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Resubmission is no longer allowed.';
  END IF;

  -- Verify all flagged documents have been replaced
  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No document submission packet found for this renewal.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    WHERE dsf.submission_id = _submission.id
      AND dsf.admin_status IN ('needs_revision', 'rejected_red')
  ) THEN
    RAISE EXCEPTION 'All documents marked for revision or rejection must be replaced before resubmission.';
  END IF;

  -- Update renewal state to resubmitted
  UPDATE public.organization_renewals
  SET
    status = 'resubmitted',
    updated_at = _now
  WHERE id = p_renewal_id;

  -- Update document submission state
  UPDATE public.document_submissions
  SET
    status = 'submitted',
    updated_at = _now
  WHERE id = _submission.id;

  -- Insert activity log with NULL actor_user_id (org user action)
  INSERT INTO public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_resubmitted',
    'renewal',
    p_renewal_id,
    format('Organization resubmitted renewal application for Cycle %s after revisions.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'resubmitted_at', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_submit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'draft' THEN
    RAISE EXCEPTION 'Renewal cannot be submitted from status "%". Expected "draft".', _renewal.status;
  END IF;

  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Application can no longer be submitted.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No renewal document submission found.';
  END IF;

  -- Each selected document may be sent as it is ready. The admin approval RPC
  -- continues to enforce completeness and approval of every required type.
  IF NOT EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    JOIN public.required_document_types rdt ON rdt.id = dsf.document_type_id
    WHERE dsf.submission_id = _submission.id
      AND rdt.is_active = true
      AND coalesce(rdt.is_required, true) = true
      AND rdt.scope IN ('renewal', 'both')
      AND rdt.template_scope = 'document_submission'
      AND nullif(trim(dsf.file_url), '') IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Upload at least one required renewal document before submitting.';
  END IF;

  UPDATE public.organization_renewals
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = p_renewal_id;

  UPDATE public.document_submissions
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = _submission.id;

  INSERT INTO public.activity_logs (
    actor_user_id, organization_id, action, related_type, related_id, description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_submitted',
    'renewal',
    p_renewal_id,
    format('Organization submitted renewal documents for Cycle %s.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'submitted_at', _now
  );
END;
$function$
